59	// configureFlowDeps contains side effects used by the interactive configure
60	// flow. Tests can replace individual operations without a keyring, browser,
61	// GitHub CLI, or live control plane.
62	type configureFlowDeps struct {
63		resolveAuth  func(context.Context) (statusTarget, error)
64		fetchProfile profileFetcher
65		runLogin     func(context.Context, io.Writer, io.Writer) error
66		accessClient func(context.Context) (configureAccessReporter, error)
67		coreClient   func() (*coreapi.Client, error)
68		openURL      browserOpenFunc
