515	type configureUpstreamField struct {
516		*huh.Select[string]
517	
518		value         *string
519		committed     string
520		highlighted   string
521		refresh       func()
522		layoutChanged func()
523		window        tea.WindowSizeMsg
524		focused       bool
525	}
