1344	func configureExistingForgeRemote(ctx context.Context, repoRoot, owner, repo string, remotes map[string]bool, exclude string) (string, error) {
1345		names := make([]string, 0, len(remotes))
1346		for name := range remotes {
1347			if name != exclude {
1348				names = append(names, name)
1349			}
1350		}
1351		sort.SliceStable(names, func(i, j int) bool {
1352			priority := func(name string) int {
1353				switch name {
1354				case mirrorCloneProviderGitHub:
1355					return 0
1356				case defaultMirrorUpstreamRemote:
1357					return 1
1358				default:
1359					return 2
1360				}
1361			}
1362			if priority(names[i]) != priority(names[j]) {
1363				return priority(names[i]) < priority(names[j])
1364			}
1365			return names[i] < names[j]
1366		})
1367		for _, name := range names {
1368			raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
1369			if err != nil {
1370				return "", fmt.Errorf("read remote %q URL: %w", name, err)
1371			}
1372			info, err := gitremote.ParseURL(raw)
1373			if err == nil && info.Protocol != gitremote.ProtocolEntire && info.Forge == mirrorUseForge &&
1374				strings.EqualFold(info.Owner, owner) && strings.EqualFold(info.Repo, repo) {
1375				return name, nil
1376			}
1377		}
1378		return "", nil
1379	}
