1429	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice, forgeRemote string, now func() time.Time) error {
1430		outW := cmd.OutOrStdout()
1431		if len(generated) == 0 {
1432			fmt.Fprintln(outW, "  No new configuration changes to commit.")
1433			return nil
1434		}
1435		if len(before) != 0 {
1436			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1437			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1438			return nil
1439		}
1440	
1441		if branch == "" {
1442			return errors.New("cannot save configuration from a detached HEAD")
1443		}
1444		if protected && choice == configureSaveDirect {
1445			return fmt.Errorf("%s is protected; push to a new branch", branch)
1446		}
1447		if choice != configureSaveDirect && choice != configureSaveNewBranch {
1448			return fmt.Errorf("unknown save choice %q", choice)
1449		}
1450		if forgeRemote == "" {
1451			return errors.New("no GitHub remote available for configuration push")
1452		}
1453	
1454		pushBranch := branch
1455		switchedBranch := false
1456		configurationCommitted := false
1457		if choice == configureSaveNewBranch {
1458			var err error
1459			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, forgeRemote, now)
1460			if err != nil {
1461				return err
1462			}
1463			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1464				return fmt.Errorf("create configuration branch: %w", err)
1465			}
1466			switchedBranch = true
1467			defer func() {
1468				if switchedBranch {
1469					// Best-effort fallback for failures after branch creation. Successful
1470					// paths restore explicitly below so an error can be returned.
1471					if restoreErr := restoreConfigureOriginalBranch(context.WithoutCancel(cmd.Context()), repoRoot, pushBranch, branch, generated, configurationCommitted); restoreErr != nil {
1472						fmt.Fprintf(cmd.ErrOrStderr(), "warning: could not return configuration to original branch %q: %v\n", branch, restoreErr)
1473					}
1474				}
1475			}()
1476		}
1477	
1478		args := []string{"add", "--"}
1479		args = append(args, generated...)
1480		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1481			return fmt.Errorf("stage configuration: %w", err)
1482		}
1483		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1484			return fmt.Errorf("commit configuration: %w", err)
1485		}
1486		configurationCommitted = true
1487		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1488		if err != nil {
1489			return fmt.Errorf("read configuration commit: %w", err)
1490		}
1491		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1492		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", forgeRemote, pushBranch); err != nil {
1493			return fmt.Errorf("push configuration to GitHub remote %q: %w", forgeRemote, err)
1494		}
1495		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", forgeRemote, pushBranch)
1496		if choice == configureSaveNewBranch {
1497			if err := restoreConfigureOriginalBranch(cmd.Context(), repoRoot, pushBranch, branch, generated, configurationCommitted); err != nil {
1498				return err
1499			}
1500			switchedBranch = false
1501			fmt.Fprintf(outW, "✓ Returned to %s with configuration applied locally\n", branch)
1502			fmt.Fprintln(outW, "  Open a trail to merge it:")
1503			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
