1508	func restoreConfigureOriginalBranch(ctx context.Context, repoRoot, sourceBranch, originalBranch string, generated []string, committed bool) error {
1509		if _, err := gitRunner(ctx, repoRoot, "switch", originalBranch); err != nil {
1510			return fmt.Errorf("return to original branch %q: %w", originalBranch, err)
1511		}
1512	
1513		var args []string
1514		if committed {
1515			// Switching to the original branch removes files introduced by the
1516			// configuration commit. Restore only the generated paths from the review
1517			// branch into the worktree, without touching the original branch's index,
1518			// so the repository remains configured while awaiting review.
1519			args = []string{"restore", "--source", sourceBranch, "--worktree", "--"}
1520		} else {
1521			// A failure before commit can carry staged generated files across the
1522			// switch. Unstage those paths while preserving their worktree contents.
1523			args = []string{"reset", "--"}
1524		}
1525		args = append(args, generated...)
1526		if _, err := gitRunner(ctx, repoRoot, args...); err != nil {
1527			return fmt.Errorf("restore configuration on original branch %q: %w", originalBranch, err)
1528		}
1529		return nil
1530	}
